<script setup>
import RedesignTopbar from './RedesignTopbar.vue';
import './redesignTable.css';
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AdminSidebar from './AdminSidebar.vue';
import { confirmAction } from './confirmAction.js';

const props = defineProps({ quests: Object, filters: Object, selectedStudyGroup: Object, timezone: { type: String, default: 'UTC' } });
const page = usePage();
const items = computed(() => props.quests?.data || []);
const scope = computed(() => props.selectedStudyGroup?.uuid ? route('redesign.study-groups.quests', props.selectedStudyGroup.uuid) : route('redesign.quests'));
const createUrl = computed(() => props.selectedStudyGroup?.uuid ? route('redesign.study-groups.quests.create', props.selectedStudyGroup.uuid) : route('redesign.quests.create'));
const aiUrl = computed(() => props.selectedStudyGroup?.uuid ? route('redesign.study-groups.quests.generate-ai', props.selectedStudyGroup.uuid) : route('redesign.quests.generate-ai'));
const editUrl = quest => props.selectedStudyGroup?.uuid ? route('redesign.study-groups.quests.edit', { groupUuid: props.selectedStudyGroup.uuid, questUuid: quest.uuid }) : route('redesign.quests.edit', quest.uuid);
const search = ref(props.filters?.search || '');
const selectedStatus = ref(props.filters?.status || '');
const type = computed(() => props.filters?.quest_type || 'all');
const view = computed(() => props.filters?.view || 'active');
const navigate = (overrides = {}) => router.get(scope.value, { search: search.value.trim() || undefined, quest_type: type.value === 'all' ? undefined : type.value, view: view.value === 'trash' ? 'trash' : undefined, status: selectedStatus.value || undefined, ...overrides }, { preserveState: true, preserveScroll: true, replace: true });
const reset = () => { search.value = ''; selectedStatus.value = ''; router.get(scope.value, {}, { preserveState: true, replace: true }); };
const date = value => {
    if (!value) return '—';
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? '—' : new Intl.DateTimeFormat('id-ID', { timeZone: props.timezone, day: '2-digit', month: 'short', year: 'numeric' }).format(parsed);
};
const archiveQuest = async quest => { if (await confirmAction(`Arsipkan quest ${quest.title}? Quest dapat dipulihkan dari tab Arsip.`, 'Arsipkan')) router.delete(route('quests.destroy', quest.uuid), { preserveScroll: true }); };
const restoreQuest = quest => router.patch(route('quests.restore', quest.uuid), {}, { preserveScroll: true });
const deleteQuest = async quest => { if (await confirmAction(`Hapus permanen quest ${quest.title}? Semua data terkait tidak dapat dipulihkan.`, 'Hapus permanen')) router.delete(route('quests.force-destroy', quest.uuid), { preserveScroll: true }); };
const statusLabel = value => ({ Available: 'Tersedia', 'In-Progress': 'Berlangsung', Done: 'Selesai' }[value] || value || '—');
</script>

<template>
    <Head title="Quest management" />
    <div class="quests-app"><AdminSidebar /><main>
        <RedesignTopbar breadcrumb="Program belajar / Quest" />
        <div class="content">
            <div class="heading"><div><Link v-if="selectedStudyGroup" :href="route('redesign.study-groups.show', selectedStudyGroup.uuid)" class="back">← {{ selectedStudyGroup.name }}</Link><h1>Quest management</h1><p>Kelola quest, tantangan, dan progres peserta.</p></div><div class="heading-actions"><Link class="ai-link" :href="aiUrl">✦ Generate quest with AI</Link><Link class="add" :href="createUrl">+ Buat quest</Link></div></div>
            <div class="tabs" role="group" aria-label="Jenis quest"><button type="button" :class="{ active: view !== 'trash' && type === 'all' }" @click="navigate({ view: undefined, quest_type: undefined })">Semua quest</button><button type="button" :class="{ active: view !== 'trash' && type === 'main' }" @click="navigate({ view: undefined, quest_type: 'main' })">Main</button><button type="button" :class="{ active: view !== 'trash' && type === 'optional' }" @click="navigate({ view: undefined, quest_type: 'optional' })">Optional</button><button type="button" :class="{ active: view === 'trash' }" @click="navigate({ view: 'trash', quest_type: undefined, status: undefined })">Arsip</button></div>
            <form class="filters" @submit.prevent="navigate()"><input v-model="search" aria-label="Cari quest" placeholder="Cari nama quest atau kelas..." /><select v-model="selectedStatus" aria-label="Filter status" :disabled="view === 'trash'"><option value="">Semua status</option><option value="Available">Tersedia</option><option value="In-Progress">Berlangsung</option><option value="Done">Selesai</option></select><button type="submit">Filter</button><button type="button" @click="reset">Reset</button></form>
            <section class="panel"><h2>Daftar quest</h2><div v-if="!items.length" class="empty">{{ search ? 'Tidak ada quest yang cocok.' : 'Belum ada quest pada tampilan ini.' }}</div><div v-else class="table-wrap"><table><thead><tr><th>Quest</th><th>Kelas / tipe</th><th>Deadline</th><th>Reward</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="quest in items" :key="quest.uuid"><td class="quest-name"><strong>{{ quest.title || quest.name }}</strong></td><td>{{ quest.study_group?.name || 'Umum' }}<small>{{ quest.quest_type === 'optional' ? 'Optional' : 'Main' }}</small></td><td>{{ date(quest.deadline) }}</td><td>{{ quest.reward_exp || 0 }} XP · {{ quest.reward_gold || 0 }} Gold</td><td><span class="status" :class="{ archived: view === 'trash' }">{{ view === 'trash' ? 'Arsip' : statusLabel(quest.status) }}</span></td><td><div v-if="view !== 'trash'" class="actions"><Link :href="route('quests.user-preview', quest.uuid)">User View</Link><Link :href="route('redesign.quests.submissions', quest.uuid)">Submissions</Link><Link :href="editUrl(quest)">Edit</Link><button type="button" class="danger" @click="archiveQuest(quest)">Arsipkan</button></div><div v-else class="actions"><button type="button" @click="restoreQuest(quest)">Pulihkan</button><button type="button" class="danger" @click="deleteQuest(quest)">Hapus permanen</button></div></td></tr></tbody></table></div><div class="footer"><span>Menampilkan {{ items.length }} dari {{ quests.total }} quest</span><div v-if="quests.links?.length > 3" class="pager"><Link v-for="(link, index) in quests.links" :key="index" :href="link.url || '#'" :class="{ active: link.active, disabled: !link.url }" :aria-disabled="!link.url" preserve-scroll v-html="link.label" /></div></div></section>
        </div>
    </main></div>
</template>

<style scoped>
