us{color:#007f78;font-weight:700}.status.archived{color:#70858c}.actions{display:flex;gap:12px;white-space:nowrap}.actions a,.actions button{color:#007f78;text-decoration:underline;text-underline-offset:3px}.actions button{border:0;background:transparent;padding:0;font:inherit;cursor:pointer}.actions button.danger{color:#ad3d3d}.footer{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-top:22px;color:#70858c;font-size:11px}.pager{display:flex;gap:5px;flex-wrap:wrap}.pager a{border:1px solid #dce6e8;border-radius:5px;padding:6px 9px;color:#007f78;text-decoration:none}.pager a.active{background:#e5f5f1;font-weight:700}.pager a.disabled{opacity:.4;pointer-events:none}.empty{color:#70858c;font-size:13px;padding:20px}.quests-app :is(a,button,input,select):focus-visible{outline:2px solid #008b83;outline-offset:2px}@media(max-width:800px){.quests-app{display:block}}@media(max-width:650px){.content{padding:22px 14px}.heading{align-items:stretch;flex-direction:column}.heading h1{font-size:25px}.panel{padding:16px}.filters{grid-template-columns:1fr 1fr}.filters input,.filters select{grid-column:1/-1}}
</style>
